 if(tab==='events'){if(!events.length)list.append(node('p','Waiting for a completed transfer. No event schedule feeds the detector.','vt-empty'));for(const e of [...events].reverse()){const card=node('article',undefined,'vt-event'),head=node('div',undefined,'vt-event-head');head.append(node('span',e.type==='shot'?'SHOT CANDIDATE':e.type.toUpperCase()),node('time',e.end.toFixed(1)+'s'));card.append(head,node('h3',identity(e.from)+(e.to?' → '+identity(e.to):'')),node('p',`${format(e.distance)} m · ${format(e.speed)} km/h`));const certainty=node('span',`${e.confidenceLabel||'REVIEW'} EVIDENCE SUPPORT · ${Math.round((e.confidence||0)*100)}%`,'vt-confidence');certainty.dataset.level=(e.confidenceLabel||'review').toLowerCase();card.append(certainty);if(e.quality)card.append(node('span',`${e.quality.difficulty}/100 difficulty · synthetic model`,'vt-difficulty'));const d=node('details');d.dataset.event=e.id;d.open=expanded.has(e.id);d.append(node('summary','Why this rating / source frames'));d.append(node('p',e.quality?`At release: ${format(e.quality.distance)} m to receiver, ${format(e.quality.pressure)} m nearest defender, ${format(e.quality.clearance)} m lane clearance. ${format(e.quality.completion*100,0)}% synthetic-model completion estimate.`:'Directional ball flight toward the goal mouth. No calibrated height or goal-line outcome.'));d.append(node('small',`Decoded frames ${e.evidence.firstFrame}–${e.evidence.lastFrame}. Evidence support is a heuristic, not a calibrated probability. It combines observed flight samples, sustained reception and both enrolled identities. Speed uses a linear fit to observed ball positions, metres → kilometres per hour.`));card.append(d);list.append(card);}}
