function draw(){ctx.clearRect(0,0,overlay.width,overlay.height);if(!current)return;const o=options(),toPixel=p=>worldToPixel(p,cal);ctx.font='700 18px Arial';for(const p of current.players){const q=toPixel(p),accent=p.team==='harbor'?'#dbf260':'#55c8ff';if(o.trails){const track=tracker.tracks.get(p.id);ctx.save();ctx.beginPath();track.history.forEach((h,i)=>{const v=toPixel(h);i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y);});ctx.strokeStyle=accent;ctx.lineWidth=5;ctx.shadowColor=accent;ctx.shadowBlur=14;ctx.stroke();ctx.restore();ctx.beginPath();ctx.arc(q.x,q.y-4,27,0,Math.PI*2);ctx.fillStyle=p.team==='harbor'?'rgba(219,242,96,.13)':'rgba(85,200,255,.13)';ctx.fill();ctx.strokeStyle=accent;ctx.lineWidth=3;ctx.stroke();}if(o.labels){const text=p.name.split(' ').at(-1)+(p.speed>20?'  '+format(p.speed)+' KM/H':''),w=ctx.measureText(text).width+24,x=Math.min(cal.width-w-8,Math.max(8,q.x-w/2));ctx.fillStyle='rgba(5,11,18,.9)';ctx.fillRect(x,q.y-82,w,30);ctx.fillStyle=accent;ctx.fillRect(x,q.y-82,5,30);ctx.fillStyle='#fff';ctx.fillText(text,x+13,q.y-60);}}if(current.ball&&o.trails){const q=toPixel(current.ball);ctx.save();ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.shadowColor='#eaff72';ctx.shadowBlur=18;ctx.beginPath();ctx.arc(q.x,q.y,18,0,Math.PI*2);ctx.stroke();ctx.restore();}const latest=current.events.at(-1);if(latest){const from=current.players.find(p=>p.id===latest.from),to=current.players.find(p=>p.id===latest.to);if(from&&to){const a=toPixel(from),b=toPixel(to);ctx.save();ctx.setLineDash([16,10]);ctx.strokeStyle='#ffb52d';ctx.lineWidth=6;ctx.shadowColor='#ffb52d';ctx.shadowBlur=12;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.restore();}}}
function process(t){if(!tracker||busy||Math.abs(t-lastTime)<.085)return;busy=true;try{pc.drawImage(video,0,0,480,320);const frame=detector(pc.getImageData(0,0,480,320).data,480,320,options());current=tracker.update(frame,t);lastTime=t;hasRun=true;panel.querySelector('.vt-export').disabled=false;draw();panel.querySelector('.vt-status').textContent=`LIVE ANALYSIS · ${t.toFixed(1)} / 60 s · ${current.status}`;const start=panel.querySelector('[data-action="start"]');start.textContent=`ANALYZING · ${String(Math.floor(t)).padStart(2,'0')} / 60 s`;start.classList.add('is-live');if(current.events.length!==eventCount||t-lastPaint>.8||t<lastPaint){if(current.events.length!==eventCount){challenged=false;aiPosts=[];aiState='';}eventCount=current.events.length;lastPaint=t;render();}}catch(e){video.pause();panel.querySelector('.vt-status').textContent='Analysis stopped: '+e.message;}finally{busy=false;}}
function next(){if(video.requestVideoFrameCallback)video.requestVideoFrameCallback((_,meta)=>{if(!video.paused)process(meta.mediaTime);next();});else requestAnimationFrame(()=>{if(!video.paused)process(video.currentTime);next();});}
function rewind(){programmaticSeek=true;video.currentTime=0;setTimeout(()=>{programmaticSeek=false;},250);}
async function startAnalysis(){if(!tracker)return;clear();analysisStarted=true;rewind();video.muted=true;panel.querySelector('[data-action="start"]').textContent='STARTING LIVE ANALYSIS…';panel.querySelector('.vt-status').textContent='Opening the measured video stream…';render();try{await video.play();}catch{analysisStarted=false;render();panel.querySelector('[data-action="start"]').textContent='▶ Analyze the full minute';panel.querySelector('.vt-status').textContent='Playback needs one tap. Select Start live analysis in the evidence desk.';}}
panel.querySelector('[data-action="start"]').onclick=startAnalysis;
panel.querySelector('[data-action="reset"]').onclick=()=>{video.pause();rewind();analysisStarted=false;clear();const start=panel.querySelector('[data-action="start"]');start.textContent='▶ Analyze the full minute';start.classList.remove('is-live');panel.querySelector('.vt-status').textContent='Reset complete · ready for a new measured run';};
video.addEventListener('seeking',()=>{if(programmaticSeek)return;clear();panel.querySelector('.vt-status').textContent='Seek detected. Analyze forward to build new evidence.';});
for(const b of panel.querySelectorAll('[data-tab]'))b.onclick=()=>{tab=b.dataset.tab;panel.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();};
for(const c of panel.querySelectorAll('[data-option]'))c.onchange=()=>{if(['occludeBall','hideTracking'].includes(c.dataset.option)){clear();panel.querySelector('.vt-status').textContent='Evidence changed. Analysis restarted at the current video time.';}else draw();};
panel.querySelector('.vt-export').onclick=()=>{if(!hasRun)return;const blob=new Blob([JSON.stringify({source:'compressed synthetic video pixels',calibration:cal,cutoff:current.t,detector_health:current.detectorHealth,events:current.events,discussion:aiPosts,discussion_status:aiState,players:current.players,method:model.method,limitations:validation?.limits},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download='btr-pixel-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.addEventListener('visibilitychange',()=>{if(document.hidden)video.pause();});
document.addEventListener('click',()=>setTimeout(()=>{if(lab.hidden)video.pause();updateScope();},0));
try{[cal,model,validation,holdout]=await Promise.all(['calibration.json','pass-model.json','validation.json','holdout.json'].map(async name=>{const r=await fetch('assets/tracking/'+name);if(!r.ok)throw Error(name+' unavailable');return r.json();}));detector=createPixelDetector(cal);tracker=new VideoTracker(cal,model);overlay.width=cal.width;overlay.height=cal.height;panel.querySelector('.vt-status').textContent='Ready · fixed-camera calibration loaded · no cloud requests';render();next();}catch(e){panel.querySelector('.vt-status').textContent='Tracking unavailable: '+e.message;panel.querySelector('[data-action="start"]').disabled=true;}

async function askAI(){
 const e=current?.events.at(-1);if(!e||aiBusy)return;video.pause();const epoch=++aiEpoch;aiBusy=true;aiPosts=[];aiState='Connecting to the evidence desk…';aiAbort=new AbortController();render();
 try{const base=location.hostname==='127.0.0.1'||location.hostname==='localhost'?'':'https://before-the-roar.icypebble-9d6c9f05.eastus2.azurecontainerapps.io';const r=await fetch(base+'/api/video-desk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({time:current.t,eventTime:e.end,from:e.from,type:e.type,tracking:!!current.ball&&!!current.players.length,challenge:challenged,language:'en',mode:'fan'}),signal:aiAbort.signal});if(!r.ok)throw Error('AI desk unavailable ('+r.status+')');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',complete=false;while(true){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;while((end=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,end);buffer=buffer.slice(end+2);const type=frame.match(/^event: (.+)$/m)?.[1],raw=frame.match(/^data: (.+)$/m)?.[1];if(!raw)continue;const data=JSON.parse(raw);if(epoch!==aiEpoch)return;if(type==='post'){aiPosts=aiPosts.filter(p=>p.role!==data.role);aiPosts.push(data);aiState='Received '+data.role;render();}if(type==='complete'){complete=true;aiState=data.error?'Some AI responses unavailable: '+data.error:(data.cached?'Saved AI discussion recovered.':'Live AI discussion complete.')+' Wording is constrained to the event’s evidence-backed catalog.';}if(type==='error')throw Error(data.message||'AI interrupted');}}if(!complete)throw Error('Discussion interrupted. Retry to recover.');}
 catch(e){if(epoch!==aiEpoch)return;aiState=e.name==='AbortError'?'Discussion cancelled after evidence changed.':e.message;}finally{if(epoch===aiEpoch){aiBusy=false;render();}}
}

panel.querySelector('[data-action="camera"]').onclick=()=>{const close=panel.querySelector('.vt-screen').classList.toggle('vt-close');video.controls=false;const button=panel.querySelector('[data-action="camera"]');button.setAttribute('aria-pressed',String(close));button.textContent=close?'Return to full pitch':'Broadcast close-up';};
panel.querySelector('[data-action="pause"]').onclick=()=>{if(video.paused)video.play().catch(()=>{panel.querySelector('.vt-status').textContent='Use Analyze to restart playback.';});else video.pause();};

video.addEventListener('play',()=>{if(aiBusy||aiPosts.length){cancelAI();render();}});

function updateScope(){const tag=lab.querySelector('.lab-source-tag');if(tag)tag.textContent=panel.hidden?'INDEPENDENT SYNTHETIC FIXTURE':'CONTINUOUS MEASURED VIDEO';if(!lab.hidden){const summary=document.querySelector('.source-map summary');if(summary)summary.textContent=(panel.hidden?'Full-match generator':'Measured stadium minute')+' · source & scope';}}
updateScope();

// Opening Match Lab is itself the viewer's playback gesture. Start the measured
// minute immediately so the evidence desk never looks like a broken empty panel.
document.addEventListener('click',event=>{const trigger=event.target.closest?.('#lab-nav,[data-jump="lab"],.btr-enter');if(trigger&&!analysisStarted&&!hasRun)setTimeout(()=>{if(!lab.hidden)startAnalysis();},0);});

for(const button of panel.querySelectorAll('[data-evidence]'))button.onclick=()=>{if(!current?.events.length)return;video.pause();openVideoEvidence({snapshot:current,frame:pixels.toDataURL('image/png'),posts:videoStory(current,cal.roster,{challenge:challenged}).map(p=>aiPosts.find(a=>a.role===p.role)||p)},button.dataset.evidence);};



